function tri(n: number): number[] {
    if (n === 0) {
        return [1];
    }
    let myTri: number[] = [1, 3];
    for (let i = 2; i <= n; i++) {
        if (i % 2 === 0) {
            myTri.push(i / 2 + 1);
        } else {
            myTri.push(myTri[i - 1] + myTri[i - 2] + (i + 3) / 2);
        }
    }
    return myTri;
}

function maximum(arr: number[], k: number): number[] {
    if (k === 0) {
        return [];
    }
    arr.sort((a, b) => a - b);
    const ans = arr.slice(-k);
    return ans;
}

import { countBy } from 'lodash';

function remove_duplicates(numbers: number[]): number[] {
    const c = countBy(numbers);
    return numbers.filter(n => c[n] <= 1);
}

function is_prime(n: number): boolean {
    if (n < 2) return false;
    for (let k = 2; k < n - 1; k++) {
        if (n % k === 0) return false;
    }
    return true;
}

function add(x: number, y: number): number {
    return x + y;
}

function sum_to_n(n: number): number {
    return (n * (n + 1)) / 2;
}

function double_the_difference(lst: number[]): number {
    return lst.filter(i => i > 0 && i % 2 !== 0 && !str(i).includes('.')).reduce((acc, i) => acc + i ** 2, 0);
}

function str(num: number): string {
    return num.toString();
}

function digits(n: number): number {
    let product = 1;
    let oddCount = 0;
    for (const digit of n.toString()) {
        const intDigit = parseInt(digit);
        if (intDigit % 2 === 1) {
            product *= intDigit;
            oddCount += 1;
        }
    }
    return oddCount === 0 ? 0 : product;
}

function has_close_elements(numbers: number[], threshold: number): boolean {
    for (let idx = 0; idx < numbers.length; idx++) {
        for (let idx2 = 0; idx2 < numbers.length; idx2++) {
            if (idx !== idx2) {
                const distance = Math.abs(numbers[idx] - numbers[idx2]);
                if (distance < threshold) {
                    return true;
                }
            }
        }
    }
    return false;
}

function odd_count(lst: string[]): string[] {
