        return `the number of odd elements ${n}n the str${n}ng ${n} of the ${n}nput.`;
    });
}

function sort_even(l: number[]): number[] {
    const evens = l.filter((_, index) => index % 2 === 0).sort((a, b) => a - b);
    const odds = l.filter((_, index) => index % 2 !== 0);
    let ans: number[] = [];
    for (let i = 0; i < Math.min(evens.length, odds.length); i++) {
        ans.push(evens[i], odds[i]);
    }
    if (evens.length > odds.length) {
        ans.push(evens[evens.length - 1]);
    }
    return ans;
}

function find_closest_elements(numbers: number[]): [number, number] {
    let closestPair: [number, number] | null = null;
    let distance: number | null = null;

    for (let idx = 0; idx < numbers.length; idx++) {
        for (let idx2 = 0; idx2 < numbers.length; idx2++) {
            if (idx !== idx2) {
                const newDistance = Math.abs(numbers[idx] - numbers[idx2]);
                if (distance === null || newDistance < distance) {
                    distance = newDistance;
                    closestPair = [numbers[idx], numbers[idx2]].sort((a, b) => a - b) as [number, number];
                }
            }
        }
    }

    return closestPair!;
}

