function is_nested(input: string): boolean {
    const opening_bracket_index: number[] = [];
    const closing_bracket_index: number[] = [];

    for (let i = 0; i < input.length; i++) {
        if (input[i] === '[') {
            opening_bracket_index.push(i);
        } else {
            closing_bracket_index.push(i);
        }
    }

    closing_bracket_index.reverse();

    let cnt = 0;
    let i = 0;
    const l = closing_bracket_index.length;

    for (const idx of opening_bracket_index) {
        if (i < l && idx < closing_bracket_index[i]) {
            cnt += 1;
            i += 1;
        }
    }

    return cnt >= 2;
}

function digits_sum(n: number): number {
    let neg = 1;
    if (n < 0) {
        n = -n;
        neg = -1;
    }
    const digits = n.toString().split('').map(Number);
    digits[0] *= neg;
    return digits.reduce((acc, digit) => acc + digit, 0);
}

function order_by_points(nums: number[]): number[] {
    return nums.sort((a, b) => digits_sum(a) - digits_sum(b));
}

function vowels_count(s: string): number {
    const vowels = 'aeiouAEIOU';
    let n_vowels = 0;
    for (const c of s) {
        if (vowels.includes(c)) {
            n_vowels++;
        }
    }
    if (s.endsWith('y') || s.endsWith('Y')) {
        n_vowels++;
    }
    return n_vowels;
}

function right_angle_triangle(a: number, b: number, c: number): boolean {
    return a * a === b * b + c * c || b * b === a * a + c * c || c * c === a * a + b * b;
}

function circular_shift(x: number, shift: number): string {
    let s = x.toString();
    if (shift > s.length) {
        return s.split('').reverse().join('');
    } else {
        return s.slice(-shift) + s.slice(0, -shift);
    }
}

function pluck(arr: number[]): number[] {
    if (arr.length === 0) {
        return [];
    }
    const evens = arr.filter(x => x % 2 === 0);
    if (evens.length === 0) {
        return [];
    }
    const minEven = Math.min(...evens);
    const index = arr.indexOf(minEven);
    return [minEven, index];
}

function modp(n: number, p: number): number {
    let ret = 1;
    for (let i = 0; i < n; i++) {
        ret = (2 * ret) % p;
    }
    return ret;
}

function get_closest_vowel(word: string): string {
    if (word.length < 3) {
        return '';
    }
    const vowels = new Set(['a', 'e', 'i', 'o', 'u', 'A', 'E', 'O', 'U', 'I']);
    for (let i = word.length - 2; i > 0; i--) {
        if (vowels.has(word[i])) {
            if (!vowels.has(word[i + 1]) && !vowels.has(word[i - 1])) {
                return word[i];
            }
        }
    }
    return '';
}

