    if (numbers.Count < 2) {
        throw new ArgumentException("List must contain at least two elements.");
    }

    float? distance = null;
    Tuple<float, float> closestPair = null;

    for (int idx = 0; idx < numbers.Count; idx++) {
        for (int idx2 = idx + 1; idx2 < numbers.Count; idx2++) {
            float newDistance = Math.Abs(numbers[idx] - numbers[idx2]);
            if (!distance.HasValue || newDistance < distance.Value) {
                distance = newDistance;
                closestPair = Tuple.Create(Math.Min(numbers[idx], numbers[idx2]), Math.Max(numbers[idx], numbers[idx2]));
            }
        }
    }

    return closestPair;
}

