            y++
        } else {
            y--
        }
        if y < 0 {
            u = 0
            break
        }
    }
    if u == 1 && y == 0 {
        return "Yes"
    }
    w1 = lst[1] + lst[0]
    y = 0
    u = 1
    for i := range w1 {
