public static Tuple<float, float> FindClosestElements(List<float> numbers) {
    if (numbers == null || numbers.Count < 2) {
        throw new ArgumentException("List must contain at least two elements.");
    }

    float? distance = null;
    Tuple<float, float> closestPair = null;

    for (int i = 0; i < numbers.Count; i++) {
        for (int j = 0; j < numbers.Count; j++) {
            if (i != j) {
                float a = numbers[i];
                float b = numbers[j];

                float newDistance = Math.Abs(a - b);
                if (!distance.HasValue || newDistance < distance.Value) {
                    distance = newDistance;
                    closestPair = Tuple.Create(Math.Min(a, b), Math.Max(a, b));
                }
            }
        }
    }

    return closestPair;
}

