    let mut dict = HashMap::new();
    for &num in &numbers {
        *dict.entry(num).or_insert(0) += 1;
    }
    numbers.into_iter().filter(|&x| dict[&x] <= 1).collect()
}

fn is_prime(n: isize) -> bool {
    if n < 2 {
        return false;
    }
    for k in 2..n - 1 {
        if n % k == 0 {
            return false;
        }
    }
    true
}

