fn sort_even(l: Vec<isize>) -> Vec<isize> {
    let mut even: Vec<_> = l.iter().enumerate()
        .filter_map(|(i, &item)| if i % 2 == 0 { Some(item) } else { None })
        .collect();
    even.sort_unstable();
    l.iter().enumerate()
        .map(|(i, &item)| if i % 2 == 0 { even[i / 2] } else { item })
        .collect()
}

fn find_closest_elements(numbers: Vec<f64>) -> (f64, f64) {
    let mut closest_pair = (0.0, 0.0);
    let mut distance = None;

    for i in 0..numbers.len() {
        for j in 0..numbers.len() {
            if i != j {
                let a = numbers[i];
                let b = numbers[j];
                let new_distance = (a - b).abs();

                if distance.is_none() || new_distance < distance.unwrap() {
                    distance = Some(new_distance);
                    closest_pair = if a < b { (a, b) } else { (b, a) };
                }
            }
        }
    }

    closest_pair
}

fn is_palindrome(text: String) -> bool {
