fn is_nested(string: String) -> bool {
    let mut opening_bracket_index = Vec::new();
    let mut closing_bracket_index = Vec::new();

    for (i, c) in string.chars().enumerate() {
        if c == '[' {
            opening_bracket_index.push(i);
        } else {
            closing_bracket_index.push(i);
        }
    }

    closing_bracket_index.reverse();

    let mut cnt = 0;
    let mut i = 0;
    let l = closing_bracket_index.len();

    for k in opening_bracket_index.iter() {
        if i < l && *k < closing_bracket_index[i] {
            cnt += 1;
            i += 1;
        }
    }

    cnt >= 2
}

fn order_by_points(mut nums: Vec<isize>) -> Vec<isize> {
    let mut p = &mut nums;
    for j in (0..p.len() - 1).rev() {
        for k in 0..=j {
            let mut m = 0;
            let mut n = 0;
            let h = p[k];
            let d = p[k + 1];
            let mut y = 1;
            let mut u = 1;
            if h < 0 { y = -1; }
            if d < 0 { u = -1; }
            let mut h_abs = h.abs();
            while h_abs >= 10 {
                m += h_abs % 10;
                h_abs /= 10;
            }
            m += y * h_abs;
            let mut d_abs = d.abs();
            while d_abs >= 10 {
                n += d_abs % 10;
                d_abs /= 10;
            }
            n += u * d_abs;
            if m > n {
                p.swap(k, k + 1);
            }
        }
    }
    nums
}

