fn pluck(arr: Vec<isize>) -> Vec<isize> {
    if arr.is_empty() { return vec![]; }
    let evens: Vec<isize> = arr.into_iter().filter(|&x| x % 2 == 0).collect();
    if evens.is_empty() { return vec![]; }
    let min_even = *evens.iter().min().unwrap();
    vec![min_even, arr.iter().position(|&x| x == min_even).unwrap() as isize]
}

