fn sort_array(mut array: Vec<isize>) -> Vec<isize> {
    let tot = array[0] + array[array.len() - 1];
    for j in 0..array.len() {
        let mut ind = j;
        for k in (j + 1)..array.len() {
            if (tot % 2 == 1 && array[k] < array[ind]) || (tot % 2 == 0 && array[k] > array[ind]) {
                ind = k;
            }
        }
        array.swap(j, ind);
    }
    array
}

