fn fib4(n: isize) -> isize {
    let mut results = vec![0, 0, 2, 0];
    if n < 4 {
        return results[n as usize];
    }
    for i in 4..=n {
        let next_value = results.last().unwrap() + results.get(results.len() - 2).unwrap() +
                         results.get(results.len() - 3).unwrap() + results.first().unwrap();
        results.push(next_value);
        results.remove(0);
    }
    *results.last().unwrap()
}

