fn words_in_sentence(sentence: String) -> String {
    let t: Vec<&str> = sentence.split_whitespace().collect();
    let mut p = String::new();

    for word in t.iter() {
        let len = word.len();
        if len <= 1 { continue; }
        let is_prime = (2..=(len as f64).sqrt() as usize).all(|i| word.parse::<usize>().unwrap() % i != 0);
        if !is_prime { continue; }

        if p.is_empty() {
            p.push_str(word);
        } else {
            p.push(' ');
            p.push_str(word);
        }
    }

    p
}

