    std::copy_if(arr.begin(), arr.end(), std::back_inserter(evens), [](long x) { return x % 2 == 0; });
    if (evens.empty()) return {};
    auto min_it = std::min_element(evens.begin(), evens.end());
    long min_val = *min_it;
    long index = std::distance(arr.begin(), std::find(arr.begin(), arr.end(), min_val));
    return {min_val, index};
}

