func find_closest_elements(numbers: [Double]) -> (Double, Double) {
    var closest_pair: (Double, Double)?
    var distance: Double?

    for i in 0..<numbers.count {
        for j in 0..<numbers.count where i != j {
            let a = numbers[i]
            let b = numbers[j]

            if distance == nil {
                distance = abs(a - b)
                closest_pair = (min(a, b), max(a, b))
            } else {
                let new_distance = abs(a - b)
                if new_distance < distance! {
                    distance = new_distance
                    closest_pair = (min(a, b), max(a, b))
                }
            }
        }
    }

    return closest_pair!
}

