            if p[k] < 0 { y = -1 }
            if p[k + 1] < 0 { u = -1 }
            while h >= 10 {
                m += h % 10
                h /= 10
            }
            m += y * h
            while d >= 10 {
                n += d % 10
                d /= 10
            }
            n += u * d
            if m > n {
