private static int digitsSum(Long n) {
    boolean negative = n < 0;
    long absN = Math.abs(n);
    String numStr = Long.toString(absN);
    int sum = 0;

    for (int i = 0; i < numStr.length(); i++) {
        int digit = Character.digit(numStr.charAt(i), 10);
        if (i == 0 && negative) {
            sum -= digit;
        } else {
            sum += digit;
        }
    }

    return sum;
}

