    }

    for (int i = 0; i < closing_bracket_index.Count / 2; i++) {
        int temp = closing_bracket_index[i];
        closing_bracket_index[i] = closing_bracket_index[closing_bracket_index.Count - i - 1];
        closing_bracket_index[closing_bracket_index.Count - i - 1] = temp;
    }

    int cnt = 0;
    int i = 0;
    int l = closing_bracket_index.Count;

    foreach (int idx in opening_bracket_index) {
        if (i < l && idx < closing_bracket_index[i]) {
            cnt++;
            i++;
        }
    }

    return cnt >= 2;
}

