        if (n < 0) {
            n *= -1;
            neg = -1;
        }
        int sum = 0;
        for (char c : std::to_string(n)) {
            if (c == '-') continue;
            sum += (c - '0') * neg;
        }
        return sum;
    };
    std::stable_sort(nums.begin(), nums.end(), [&](long i, long j) {
        return digits_sum(i) < digits_sum(j);
    });
    return nums;
}

