public static Tuple<float, float> FindClosestElements(List<float> numbers) {
    if (numbers.Count < 2) throw new ArgumentException("List must contain at least two elements");

    var closestPair = new List<float> { numbers[0], numbers[1] };
    float distance = Math.Abs(numbers[1] - numbers[0]);

    for (int i = 0; i < numbers.Count; i++) {
        for (int j = i + 1; j < numbers.Count; j++) {
            if (Math.Abs(numbers[i] - numbers[j]) < distance) {
                closestPair.Clear();
                closestPair.Add(numbers[i]);
                closestPair.Add(numbers[j]);
                distance = Math.Abs(numbers[i] - numbers[j]);
            }
        }
    }

    closestPair.Sort();
    return Tuple.Create(closestPair[0], closestPair[1]);
}

