    let s2 = format!("{}{}", lst[1], lst[0]);
    let mut valid = false;

    for s in vec![s1, s2] {
        let mut val = 0;
        for c in s.chars() {
            if c == '(' {
                val += 1;
            } else {
                val -= 1;
            }
            if val < 0 {
                break;
            }
        }
        if val == 0 {
            valid = true;
            break;
        }
    }

    if valid {
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}

