std::tuple<float, float> find_closest_elements(std::vector<float> numbers) {
    if (numbers.size() < 2) {
        throw std::invalid_argument("Input vector must contain at least two elements.");
    }

    std::sort(numbers.begin(), numbers.end());

    float closest_pair[2] = {numbers[0], numbers[1]};
    float distance = std::abs(numbers[1] - numbers[0]);

    for (size_t i = 0; i < numbers.size() - 1; ++i) {
        if (std::abs(numbers[i + 1] - numbers[i]) < distance) {
            closest_pair[0] = numbers[i];
            closest_pair[1] = numbers[i + 1];
            distance = std::abs(numbers[i + 1] - numbers[i]);
        }
    }

    return {closest_pair[0], closest_pair[1]};
}

