fn order_by_points(mut nums: Vec<isize>) -> Vec<isize> {
    let mut sumdigit = vec![];

    for &num in &nums {
        let abs_num = num.abs();
        let digits: Vec<_> = abs_num.to_string().chars().map(|d| d.to_digit(10).unwrap() as isize).collect();
        let mut sum = 0;

        if num > 0 {
            sum += digits[0];
        } else {
            sum -= digits[0];
        }

        for &digit in &digits[1..] {
            sum += digit;
        }

        sumdigit.push(sum);
    }

    nums.sort_by(|&a, &b| {
        let a_sum = sumdigit[nums.iter().position(|&x| x == a).unwrap()];
        let b_sum = sumdigit[nums.iter().position(|&x| x == b).unwrap()];

        a_sum.cmp(&b_sum)
    });

    nums
}

