import Foundation

func split_words(txt: String) -> Result<[String], Int> {
    if txt.contains(" ") {
        let words = txt.split(separator: " ").map { String($0) }
        return .success(words)
    } else if txt.contains(",") {
        let words = txt.split(separator: ",").map { String($0) }
        return .success(words)
    } else {
        var num = 0
        for char in txt.unicodeScalars where char.value >= 97 && char.value <= 122 && (char.value - 97) % 2 == 0 {
            num += 1
        }
        return .failure(num)
    }
}

