public static Pair<Float, Float> findClosestElements(ArrayList<Float> numbers) {
    if (numbers == null || numbers.size() < 2) {
        throw new IllegalArgumentException("List must contain at least two elements");
    }

    float closestPair = 0.0f;
    float distance = Float.MAX_VALUE;

    for (int idx = 0; idx < numbers.size(); idx++) {
        for (int idx2 = idx + 1; idx2 < numbers.size(); idx2++) {
            float newDistance = Math.abs(numbers.get(idx) - numbers.get(idx2));
            if (newDistance < distance) {
                distance = newDistance;
                closestPair = numbers.get(idx) < numbers.get(idx2) ? numbers.get(idx) : numbers.get(idx2);
            }
        }
    }

    return Pair.with(closestPair, closestPair + distance);
}

