func find_closest_elements(numbers []float64) []interface{} {
    var closestPair [2]float64
    var distance *float64

    for idx := 0; idx < len(numbers); idx++ {
        elem := numbers[idx]
        for idx2 := 0; idx2 < len(numbers); idx2++ {
            if idx != idx2 {
                elem2 := numbers[idx2]
                if distance == nil {
                    newDistance := math.Abs(elem - elem2)
                    distance = &newDistance
                    closestPair[0] = math.Min(elem, elem2)
                    closestPair[1] = math.Max(elem, elem2)
                } else {
                    newDistance := math.Abs(elem - elem2)
                    if newDistance < *distance {
                        *distance = newDistance
                        closestPair[0] = math.Min(elem, elem2)
                        closestPair[1] = math.Max(elem, elem2)
                    }
                }
            }
        }
    }

    return []interface{}{closestPair[0], closestPair[1]}
}

