use std::f64;

fn find_closest_elements(numbers: Vec<f64>) -> (f64, f64) {
    let mut closest_pair = None;
    let mut distance = None;

    for idx in 0..numbers.len() {
        let elem = numbers[idx];
        for idx2 in 0..numbers.len() {
            if idx != idx2 {
                let elem2 = numbers[idx2];
                if !distance.is_some() {
                    distance = Some((elem - elem2).abs());
                    closest_pair = Some((elem.min(elem2), elem.max(elem2)));
                } else {
                    let new_distance = (elem - elem2).abs();
                    if new_distance < distance.unwrap() {
                        distance = Some(new_distance);
                        closest_pair = Some((elem.min(elem2), elem.max(elem2)));
                    }
                }
            }
        }
    }

    closest_pair.unwrap()
}

