std::string circular_shift(long x, long shift) {
    std::string s = std::to_string(x);
    if (shift > s.length()) {
        std::reverse(s.begin(), s.end());
        return s;
    } else {
        int shiftInt = static_cast<int>(shift);
        return s.substr(s.length() - shiftInt) + s.substr(0, s.length() - shiftInt);
    }
}

