std::vector<long> pluck(std::vector<long> arr) {
    if (arr.empty()) {
        return {};
    }
    std::vector<long> evens;
    std::copy_if(arr.begin(), arr.end(), std::back_inserter(evens), [](long x) { return x % 2 == 0; });
    if (evens.empty()) {
        return {};
    }
    long minEven = *std::min_element(evens.begin(), evens.end());
    int index = std::find(arr.begin(), arr.end(), minEven) - arr.begin();
    return { minEven, index };
}

