func even_odd_palindrome(n: Int) -> (Int, Int) {
    func isPalindrome(_ number: Int) -> Bool {
        let numStr = String(number)
        return numStr == String(numStr.reversed())
    }

    var evenPalindromeCount = 0
    var oddPalindromeCount = 0

    for i in 1...n {
        if i % 2 == 1 && isPalindrome(i) {
