func tri(n: Int) -> [Int] {
    if n == 0 {
        return [1]
    }
    var myTri = [1, 3]
    for i in 2...n {
        if i % 2 == 0 {
            myTri.append(i / 2 + 1)
        } else {
            let nextValue = myTri[i - 1] + myTri[i - 2] + (i + 3) / 2
            myTri.append(nextValue)
        }
    }
    return myTri
}

