func sort_even(l: [Int]) -> [Int] {
    let evens = l.enumerated().filter { $0.offset % 2 == 0 }.map { $0.element }
    let odds = l.enumerated().filter { $0.offset % 2 != 0 }.map { $0.element }
    var ans: [Int] = []
    for i in 0..<min(evens.count, odds.count) {
        ans.append(evens[i])
        ans.append(odds[i])
