func find_closest_elements(numbers: [Double]) -> (Double, Double) {
    var closestPair: (Double, Double)? = nil
    var distance: Double? = nil

    for idx in 0..<numbers.count {
        let elem = numbers[idx]
        for idx2 in 0..<numbers.count {
            if idx != idx2 {
                let elem2 = numbers[idx2]
                if !distance!.isFinite {
                    distance = abs(elem - elem2)
                    closestPair = (min(elem, elem2), max(elem, elem2))
                } else {
                    let newDistance = abs(elem - elem2)
                    if newDistance < distance! {
                        distance = newDistance
                        closestPair = (min(elem, elem2), max(elem, elem2))
                    }
                }
            }
        }
    }

    return closestPair!
}

