func circularShift(x: Int, shift: Int) -> String {
    let s = String(x)
    if shift > s.count {
        return String(s.reversed())
    } else {
        let shiftInt = shift
        let index = s.index(s.startIndex, offsetBy: s.count - shiftInt)
        return String(s[index...]) + String(s[s.startIndex..<index])
    }
}

