long vowels_count(std::string s) {
    std::set<char> vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'};
    long n_vowels = std::count_if(s.begin(), s.end(), [&vowels](char c){ return vowels.find(c) != vowels.end(); });
    if (s.size() >= 2 && (s.back() == 'y' || s.back() == 'Y')) {
        n_vowels += 1;
    }
    return n_vowels;
}

bool right_angle_triangle(long a, long b, long c) {
    return a * a == b * b + c * c || b * b == a * a + c * c || c * c == a * a + b * b;
}

#include<string>

std::string circular_shift(long x, long shift) {
    std::string s = std::to_string(x);
    if (shift > s.size()) {
        return std::string(s.rbegin(), s.rend());
    } else {
        shift %= s.size();
        return s.substr(s.size() - shift) + s.substr(0, s.size() - shift);
    }
}

std::vector<long> pluck(std::vector<long> arr) {
    if (arr.empty()) {
        return {};
    }

    std::vector<long> evens;
    std::copy_if(arr.begin(), arr.end(), std::back_inserter(evens), [](long x) { return x % 2 == 0; });

    if (evens.empty()) {
        return {};
    }

    auto minEven = *std::min_element(evens.begin(), evens.end());
    auto index = std::find(arr.begin(), arr.end(), minEven) - arr.begin();

    return {minEven, index};
}

long modp(long n, long p) {
    long ret = 1;
    for (long i = 0; i < n; ++i) {
        ret = (2 * ret) % p;
    }
    return ret;
}

