long can_arrange(std::vector<long> arr) {
    long ind = -1;
    for (long i = 1; i < arr.size(); ++i) {
        if (arr[i] < arr[i - 1]) {
            ind = i;
        }
    }
    return ind;
}

long fib4(long n) {
    std::vector<long> results = {0, 0, 2, 0};
    if (n < 4) {
        return results[n];
    }
    for (long i = 4; i <= n; ++i) {
        long nextValue = results[1] + results[2] + results[3] + results[0];
        results.erase(results.begin());
        results.push_back(nextValue);
    }
    return results.back();
}

long max_element(std::vector<long> l) {
    long m = l[0];
    for (long e : l) {
        if (e > m) {
            m = e;
        }
    }
    return m;
}

