long is_bored(std::string S) {
    long t = 0;
    if (S.substr(0, 2) == "I ") { t = 1; }
    for (size_t i = 0; i < S.length() - 3; ++i) {
        if (S[i] == '.' || S[i] == '!' || S[i] == '?') {
            if (S[i + 1] == ' ' && S[i + 2] == 'I' && S[i + 3] == ' ') {
                t += 1;
            }
        }
    }
    return t;
}

